import { TestBed } from '@angular/core/testing';
import { Watchlist } from '../app/watchlist/watchlist';
import { WatchlistStore } from '../app/watchlist-store';

function makeMovie(id: number, title: string) {
  return { id, title, release_date: '2024-01-01', poster_path: null, overview: 'Overview' };
}

describe('Watchlist clear-seen button', () => {
  beforeEach(() => {
    localStorage.clear();
    TestBed.configureTestingModule({});
  });

  function findClearButton(fixture: any): HTMLButtonElement | null {
    const buttons: HTMLButtonElement[] = Array.from(fixture.nativeElement.querySelectorAll('button'));
    return buttons.find((b) => b.textContent?.trim() === 'Clear seen movies') ?? null;
  }

  it('removes every watched movie when clicked', () => {
    const fixture = TestBed.createComponent(Watchlist);
    const store = fixture.componentInstance.store;
    store.add(makeMovie(1, 'Seen one'));
    store.add(makeMovie(2, 'Unseen one'));
    store.toggleWatched(1);
    fixture.detectChanges();

    const button = findClearButton(fixture);
    expect(button).not.toBeNull();

    button!.click();
    fixture.detectChanges();

    expect(store.items().map((m) => m.id)).toEqual([2]);
    expect(store.count()).toBe(1);
    expect(store.watchedCount()).toBe(0);
    expect(findClearButton(fixture)).toBeNull();
  });

  it('is not rendered when no movie is watched', () => {
    const fixture = TestBed.createComponent(Watchlist);
    fixture.componentInstance.store.add(makeMovie(7, 'Only unseen'));
    fixture.detectChanges();
    expect(findClearButton(fixture)).toBeNull();
  });

  it('announces how many seen movies were removed', () => {
    const fixture = TestBed.createComponent(Watchlist);
    const store = fixture.componentInstance.store;
    store.add(makeMovie(1, 'Seen one'));
    store.add(makeMovie(2, 'Seen two'));
    store.add(makeMovie(3, 'Unseen'));
    store.toggleWatched(1);
    store.toggleWatched(2);
    fixture.detectChanges();

    const button = findClearButton(fixture)!;
    button.click();

    expect(fixture.componentInstance.announcement()).toContain('2');
  });
});
```

