    localStorage.clear();
  });

  it('clearWatched removes every watched item and keeps the others', () => {
    const store = new WatchlistStore();
    store.add(tmdbMovie(1, 'Seen one'));
    store.add(tmdbMovie(2, 'Unseen one'));
    store.add(tmdbMovie(3, 'Seen two'));
    store.toggleWatched(1);
    store.toggleWatched(3);
    expect(store.watchedCount()).toBe(2);

    store.clearWatched();

    const remaining = store.items().map((item) => item.id);
    expect(remaining).toContain(2);
    expect(remaining).toHaveLength(1);
    expect(store.count()).toBe(1);
    expect(store.watchedCount()).toBe(0);
    expect(store.items().every((item) => item.watched === false)).toBe(true);
  });

  it('clearWatched persists the cleared watchlist', () => {
    const store = new WatchlistStore();
    store.add(tmdbMovie(1, 'Seen one'));
    store.add(tmdbMovie(2, 'Unseen one'));
    store.toggleWatched(1);

    store.clearWatched();

    const reloaded = new WatchlistStore();
    expect(reloaded.items().map((item) => item.id)).toEqual([2]);
    expect(reloaded.watchedCount()).toBe(0);
  });

  it('clearWatched is a harmless no-op when nothing is watched', () => {
    const store = new WatchlistStore();
    store.add(tmdbMovie(4, 'Unseen only'));

    expect(() => store.clearWatched()).not.toThrow();

    expect(store.items().map((item) => item.id)).toEqual([4]);
  });

